  voiceRecorder.start(500);$("#voiceStatus")?.classList.add("recording");setText("#voiceStatus","Recording… read the narration while the Short plays.");setVideoMode(true);videoTime=0;videoPlaying=true;videoLast=performance.now();requestAnimationFrame(videoTick)
